//! Raw liburing bindings, generated by bindgen from the system's `liburing.h`.
//! `shim.c` exposes liburing's static inline functions (`io_uring_get_sqe`, the
//! `io_uring_prep_*` family) as `swr_uring_*`, since bindgen sees declarations only.
//!
//! Without the `liburing` feature the crate is empty.
#![cfg(feature = "liburing")]

// bindgen's output, and so which lints fire on it, differs per liburing version,
// so an expectation would go unfulfilled on some: zend-sys's exception, for the
// same reason.
mod bindings {
    #![allow(
        non_camel_case_types,
        non_upper_case_globals,
        non_snake_case,
        dead_code,
        unsafe_op_in_unsafe_fn,
        clippy::all,
        clippy::pedantic,
        clippy::restriction,
        clippy::nursery,
        reason = "generated by bindgen from liburing.h"
    )]
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub use bindings::*;
